function highlight(text,lang){
  if(lang.markup)return esc(text).replace(/(&lt;\/?)([\w-]+)/g,'$1<span class="t-tag">$2</span>').replace(/([\w-]+)=(&quot;[^&]*?&quot;|"[^"]*")/g,'<span class="t-attr">$1</span>=<span class="t-str">$2</span>').replace(/(&lt;!--[\s\S]*?--&gt;)/g,'<span class="t-com">$1</span>');
  if(!lang.kw&&!lang.line&&!lang.rem&&!lang.block)return esc(text);
  const words=new Set((lang.kw||'').split(' ').filter(Boolean).map(w=>lang.ci?w.toLowerCase():w)),bis=new Set((lang.bi||'').split(' ').filter(Boolean).map(w=>lang.ci?w.toLowerCase():w));
  let out='',i=0;const n=text.length;
  const push=(cls,s)=>{out+=cls?`<span class="${cls}">${esc(s)}</span>`:esc(s)};
  while(i<n){
    const c=text[i],rest=text.startsWith.bind(text);
    if(lang.block&&rest(lang.block[0],i)){let j=text.indexOf(lang.block[1],i+lang.block[0].length);j=j<0?n:j+lang.block[1].length;push('t-com',text.slice(i,j));i=j;continue}
    if(lang.line&&rest(lang.line,i)||(lang.hash&&c==='#')){let j=text.indexOf('\n',i);if(j<0)j=n;push('t-com',text.slice(i,j));i=j;continue}
    if(lang.rem){const ls=text.lastIndexOf('\n',i-1)+1;const head=text.slice(ls,i).trim();if(!head.replace(/^@/,'')&&(/^(@?rem)(\s|$)/i.test(text.slice(i,i+5))||rest('::',i))){let j=text.indexOf('\n',i);if(j<0)j=n;push('t-com',text.slice(i,j));i=j;continue}if(!head&&c===':'&&/\w/.test(text[i+1]||'')){let j=text.indexOf('\n',i);if(j<0)j=n;push('t-fn',text.slice(i,j));i=j;continue}}
    if(lang.triple&&(rest('"""',i)||rest("'''",i))){const q=text.slice(i,i+3);let j=text.indexOf(q,i+3);j=j<0?n:j+3;push('t-str',text.slice(i,j));i=j;continue}
    if(c==='"'||c==="'"||(c==='`'&&lang===LANG.js)){if(lang.prolog&&c==="'"){}if(lang.rem&&c==="'"){push('',c);i++;continue}let j=i+1;while(j<n&&text[j]!==c&&!(text[j]==='\n'&&c!=='`')){if(text[j]==='\\'&&!lang.rem)j++;j++}j=Math.min(n,j+1);const pre=out.endsWith('f')||/[fFrRbB]$/.test(text.slice(Math.max(0,i-1),i));push(lang.prolog&&c==="'"?'t-atom':'t-str',text.slice(i,j));i=j;continue}
    if(lang.vars){lang.vars.lastIndex=0;const m=text.slice(i).match(lang.vars);if(m&&m.index===0&&m[0].length){push('t-var',m[0]);i+=m[0].length;continue}}
    if(/[0-9]/.test(c)&&!/[\w]/.test(text[i-1]||'')){const m=text.slice(i).match(/^(0x[\da-f]+|\d[\d_]*(\.\d+)?(e[+-]?\d+)?[lLfFdD]?)/i);push('t-num',m[0]);i+=m[0].length;continue}
    if(/[A-Za-z_\u00c0-\u024f]/.test(c)){const m=text.slice(i).match(/^[\w\u00c0-\u024f]+(-[A-Z][a-z]+)?/);let w=m[0];if(lang!==LANG.ps1&&w.includes('-'))w=w.split('-')[0];const key=lang.ci?w.toLowerCase():w;const next=text.slice(i+w.length).match(/^\s*\(/);
      let cls='';if(words.has(key))cls='t-kw';else if(lang.prolog&&/^[A-Z_]/.test(w))cls='t-var';else if(bis.has(key))cls='t-bi';else if(lang===LANG.ps1&&/^[A-Z][a-z]+-[A-Z]/.test(w))cls='t-bi';else if(next)cls='t-fn';else if(/^[A-Z][a-z]/.test(w)&&['java','cs','cpp','py','js'].some(k=>LANG[k]===lang))cls='t-type';
      const prevWord=text.slice(0,i).match(/(def|class|function|void|int)\s+$/);if(prevWord)cls=prevWord[1]==='class'?'t-type':'t-fn';
      if(lang===LANG.py&&text[i-1]==='@')cls='t-dec';
      push(cls,w);i+=w.length;continue}
    if(lang===LANG.py&&c==='@'&&/[A-Za-z_]/.test(text[i+1]||'')){push('t-dec','@');i++;continue}
    if(lang.prolog&&rest(':-',i)){push('t-kw',':-');i+=2;continue}
    if(lang===LANG.ps1&&c==='-'&&/[A-Za-z]/.test(text[i+1]||'')&&/[\s(]/.test(text[i-1]||' ')){const m=text.slice(i).match(/^-\w+/);push('t-param',m[0]);i+=m[0].length;continue}
    push('',c);i++;
  }
  return out;
}

